<?php require __DIR__.'/oyunchu_config.php'; $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ga_verify();$a=$_POST['action']??'';if($a==='save'){ $id=(int)$_POST['id'];$key=trim($_POST['item_key']??'');$cat=trim($_POST['category']??'frame');$name=trim($_POST['name']??'');$price=max(0,(int)($_POST['price']??0));$style=trim($_POST['style']??'');$premium=!empty($_POST['premium_only'])?1:0;$sort=(int)($_POST['sort_order']??0);if($key===''||$name===''||$style==='')$msg='Item key, ad və style məcburidir.';else{try{if($id){$q=$conn->prepare('UPDATE oh_shop_items SET item_key=?,category=?,name=?,price=?,style=?,premium_only=?,sort_order=? WHERE id=?');$q->bind_param('sssissii',$key,$cat,$name,$price,$style,$premium,$sort,$id);}else{$q=$conn->prepare('INSERT INTO oh_shop_items(item_key,category,name,price,style,premium_only,sort_order) VALUES(?,?,?,?,?,?,?)');$q->bind_param('sssissi',$key,$cat,$name,$price,$style,$premium,$sort);}$q->execute();ga_audit('oyunchu_shop_save','oh_shop_items',$id?:$conn->insert_id,$key);$msg='Item yadda saxlanıldı.';}catch(Throwable $e){$msg='Xəta: '.$e->getMessage();}}}elseif($a==='delete'){$id=(int)$_POST['id'];$q=$conn->prepare('DELETE FROM oh_shop_items WHERE id=?');$q->bind_param('i',$id);$q->execute();ga_audit('oyunchu_shop_delete','oh_shop_items',$id);$msg='Item silindi.';}}
$edit=null;if(isset($_GET['edit'])){$q=$conn->prepare('SELECT * FROM oh_shop_items WHERE id=?');$id=(int)$_GET['edit'];$q->bind_param('i',$id);$q->execute();$edit=$q->get_result()->fetch_assoc();}$rows=$conn->query('SELECT * FROM oh_shop_items ORDER BY category,sort_order,id')->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="az" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mağaza</title><script>document.documentElement.setAttribute('data-theme',localStorage.getItem('esevgili_theme')||'dark');</script></head><body><?php include __DIR__.'/oyunchu_sidebar.php'; ?><main class="ga-main"><div class="ga-top"><b>🛍️ Oyunçu Mağazası</b></div><div class="ga-content"><?php if($msg):?><div class="ga-alert"><?=ga_h($msg)?></div><?php endif;?><div class="ga-card"><h3><?= $edit?'Item redaktə et':'Yeni item' ?></h3><form method="post" class="ga-form"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=ga_h($edit['id']??0)?>"><div><label class="ga-label">Item key *</label><input class="ga-input" name="item_key" value="<?=ga_h($edit['item_key']??'')?>" required></div><div><label class="ga-label">Kateqoriya</label><select class="ga-input" name="category"><option>frame</option><option>font</option><option>badge</option><option>avatar_icon</option></select></div><div><label class="ga-label">Ad *</label><input class="ga-input" name="name" value="<?=ga_h($edit['name']??'')?>" required></div><div><label class="ga-label">Qiymət (coin)</label><input class="ga-input" type="number" min="0" name="price" value="<?=ga_h($edit['price']??0)?>"></div><div class="full"><label class="ga-label">Style / Icon *</label><input class="ga-input" name="style" value="<?=ga_h($edit['style']??'')?>" required></div><div><label><input type="checkbox" name="premium_only" <?=!empty($edit['premium_only'])?'checked':''?>> Yalnız Premium</label></div><div><label class="ga-label">Sıra</label><input class="ga-input" type="number" name="sort_order" value="<?=ga_h($edit['sort_order']??0)?>"></div><div class="full"><button class="ga-btn ga-primary">Yadda saxla</button></div></form></div><br><div class="ga-card"><table class="ga-table"><tr><th>Item</th><th>Kateqoriya</th><th>Qiymət</th><th>Premium</th><th>Sıra</th><th></th></tr><?php foreach($rows as $r):?><tr><td><b><?=ga_h($r['name'])?></b><div class="ga-muted"><?=ga_h($r['item_key'])?></div></td><td><?=ga_h($r['category'])?></td><td>🪙 <?=number_format((int)$r['price'])?></td><td><?=((int)$r['premium_only'])?'💎':'—'?></td><td><?=$r['sort_order']?></td><td><a class="ga-btn ga-mutedbtn" href="?edit=<?=$r['id']?>">Redaktə</a> <form style="display:inline" method="post" onsubmit="return confirm('Silinsin?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="ga-btn ga-danger">Sil</button></form></td></tr><?php endforeach;?></table></div></div></main></body></html>
